const schema = (t) => ({ type: "object", properties: Object.fromEntries(Object.entries(t.props).map(([k, d]) => [k, { ...((t.types || {})[k] === "any" ? {} : { type: (t.types || {})[k] || "string" }), ...((t.types || {})[k] === "array" ? { items: {} } : {}), description: d }])), required: t.required });
export const mcpTools = (priceUsd) => TOOLS.map((t) => ({ name: t.name, description: t.description + (t.free || !priceUsd ? "" : ` Paid: $${priceUsd} USDC via x402.`), inputSchema: schema(t) }));
const ok = (id, result) => ({ jsonrpc: "2.0", id, result });
const err = (id, code, message, data) => ({ jsonrpc: "2.0", id, error: { code, message, ...(data ? { data } : {}) } });
const b64 = (o) => btoa(unescape(encodeURIComponent(JSON.stringify(o))));

export async function mcp(req, env, handle, priceUsd) {
  const H = { "content-type": "application/json", "access-control-allow-origin": "*" };
  if (req.method === "GET") return new Response(JSON.stringify({ error: "SSE stream not offered; POST JSON-RPC to this URL (MCP streamable HTTP, stateless)" }), { status: 405, headers: { ...H, allow: "POST" } });
  if (req.method === "DELETE") return new Response(null, { status: 204 });
  if (req.method !== "POST") return new Response(null, { status: 405, headers: { allow: "POST" } });
  let msg; try { msg = await req.json(); } catch { return new Response(JSON.stringify(err(null, -32700, "parse error")), { status: 400, headers: H }); }
  const batch = Array.isArray(msg), out = [];
  for (const m of batch ? msg : [msg]) { const r = await one(m, req, env, handle, priceUsd); if (r) out.push(r); }
  if (!out.length) return new Response(null, { status: 202, headers: H });
  return new Response(JSON.stringify(batch ? out : out[0]), { headers: H });
}

async function one(m, req, env, handle, priceUsd) {
  if (!m || m.jsonrpc !== "2.0" || typeof m.method !== "string") return err(m?.id ?? null, -32600, "invalid request");
  const id = m.id; if (id === undefined) return null; // notification
  switch (m.method) {
    case "initialize": return ok(id, { protocolVersion: m.params?.protocolVersion || "2025-06-18", capabilities: { tools: { listChanged: false } }, serverInfo: { name: "beggar-bot", title: "Beggar Bot", version: "0.4.0" },
      instructions: `Paid tools cost $${priceUsd} USDC on Base via x402. Call once without payment to get the 402 requirements (result._meta["x402/error"].accepts), sign an EIP-3009 transferWithAuthorization, then retry with params._meta["x402/payment"] (x402 payment payload object or base64) or the X-PAYMENT header.` });
    case "ping": return ok(id, {});
    case "tools/list": return ok(id, { tools: mcpTools(priceUsd) });
    case "tools/call": break;
    default: return err(id, -32601, "method not found");
  }
  const t = TOOLS.find((x) => x.name === m.params?.name); if (!t) return err(id, -32602, "unknown tool");
  const args = m.params?.arguments || {}, u = new URL(t.path, req.url);
  const headers = new Headers({ "user-agent": (req.headers.get("user-agent") || "") + " via-mcp", "content-type": "application/json" });
  for (const h of ["cf-connecting-ip", "x-payment", "payment-signature", "x-beggar-selftest", "x-agent"]) { const v = req.headers.get(h); if (v) headers.set(h, v); }
  let pay = m.params?._meta?.["x402/payment"];
  if (pay) { if (typeof pay === "object") pay = b64(pay); let v = 1; try { v = JSON.parse(atob(pay))?.x402Version; } catch {} headers.set(v === 2 ? "payment-signature" : "x-payment", String(pay)); }
  let init = { method: t.method, headers };
  if (t.method === "GET") for (const [k, v] of Object.entries(args)) if (v !== undefined && v !== null && v !== "") u.searchParams.set(k, String(v));
  if (t.method === "POST") init.body = JSON.stringify(args);
  let res; try { res = await handle(new Request(u, init), env); } catch (e) { return err(id, -32603, "internal error"); }
  const text = await res.text(); let body; try { body = JSON.parse(text); } catch { body = { raw: text }; }
  if (res.status === 402) return ok(id, { isError: true, content: [{ type: "text", text: JSON.stringify(body) }], _meta: { "x402/error": body } });
  const meta = {}; const pr = res.headers.get("x-payment-response") || res.headers.get("payment-response");
  if (pr) { try { meta["x402/payment-response"] = JSON.parse(atob(pr)); } catch { meta["x402/payment-response"] = pr; } }
  return ok(id, { isError: !res.ok, content: [{ type: "text", text: JSON.stringify(body) }], structuredContent: body, ...(pr ? { _meta: meta } : {}) });
}
